// Synthetic local API and static server. No external credentials or dependencies.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { resolve, relative, extname } from 'node:path';

const root = fileURLToPath(new URL('.', import.meta.url));
const rows = [{ id: 'tide', name: 'Tide', status: 'active' }, { id: 'forest', name: 'Forest', status: 'archived' }, { id: 'north', name: 'North', status: 'active' }];
let fail = false;
const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://127.0.0.1');
  if (url.pathname === '/__fixture__/mode' && request.method === 'PUT') {
    let body = ''; for await (const chunk of request) body += chunk;
    try { fail = JSON.parse(body).fail === true; response.end('{}'); } catch { response.writeHead(400).end(); }
    return;
  }
  if (request.method !== 'GET') { response.writeHead(405).end(); return; }
  if (url.pathname === '/api/projects') {
    const status = url.searchParams.get('status') || 'all';
    if (!['all', 'active', 'archived', 'paused'].includes(status)) { response.writeHead(400).end(); return; }
    await new Promise(resolve => setTimeout(resolve, status === 'active' ? 150 : 20));
    response.setHeader('Content-Type', 'application/json');
    if (fail) { response.writeHead(503).end('{"error":"fixture failure"}'); return; }
    response.end(JSON.stringify(status === 'all' ? rows : rows.filter(row => row.status === status)));
    return;
  }
  const path = resolve(root, '.' + decodeURIComponent(url.pathname === '/' ? '/index.html' : url.pathname));
  const name = relative(root, path);
  if (name.startsWith('..') || name.startsWith('.git') || name.includes('\0')) { response.writeHead(404).end(); return; }
  try {
    response.setHeader('Content-Type', ({ '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' })[extname(path)] || 'text/plain');
    response.end(await readFile(path));
  } catch { response.writeHead(404).end(); }
});
server.listen(Number(process.env.PORT || 0), '127.0.0.1', () => console.log(`http://127.0.0.1:${server.address().port}/`));

export async function projects(status = 'all') {
  const response = await fetch(`/api/projects?status=${encodeURIComponent(status)}`);
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

import { projects } from './api.js';
import { renderRows } from './ui.js';

const rows = document.querySelector('#rows');
const selection = document.querySelector('#selection');
let selected = null;
let visible = await projects();
function render() {
  renderRows(rows, visible, selected?.id, project => {
    selected = project;
    selection.textContent = project.name;
    render();
  });
}
render();

:root{--accent:#2053e8;--surface:#fff;--line:#d8dee9;--space:12px}
body{font:16px system-ui;margin:32px;background:#f6f7fa;color:#182230}header{margin-bottom:24px}
.layout{display:grid;grid-template-columns:2fr 1fr;gap:24px}.panel{background:var(--surface);padding:24px;border:1px solid var(--line);border-radius:12px}
button,select{font:inherit;padding:10px;border-radius:6px}button{border:1px solid var(--line);background:var(--surface);cursor:pointer}
.project{display:block;margin:var(--space) 0;width:100%;text-align:left}.project[aria-pressed=true]{border:2px solid var(--accent)}
:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.problem{border-left:3px solid var(--accent);padding:var(--space)}
@media(max-width:700px){.layout{grid-template-columns:1fr}body{margin:16px}}

export function selectField({ label, options, value, onChange }) {
  const wrapper = document.createElement('label');
  wrapper.append(document.createTextNode(`${label} `));
  const select = document.createElement('select');
  for (const [key, title] of options) select.add(new Option(title, key));
  select.value = value;
  select.addEventListener('change', () => onChange(select.value));
  wrapper.append(select);
  return wrapper;
}

export function renderRows(container, rows, selectedId, onSelect) {
  container.replaceChildren();
  for (const row of rows) {
    const button = document.createElement('button');
    button.className = 'project'; button.dataset.projectId = row.id;
    button.setAttribute('aria-pressed', String(selectedId === row.id));
    button.textContent = `${row.name} — ${row.status}`;
    button.addEventListener('click', () => onSelect(row));
    container.append(button);
  }
}

export function showProblem(container, retry) {
  const problem = document.createElement('div'); problem.className = 'problem';
  problem.setAttribute('role', 'alert'); problem.append('Could not load projects. ');
  const button = document.createElement('button'); button.textContent = 'Retry';
  button.addEventListener('click', retry); problem.append(button);
  container.replaceChildren(problem);
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { projects } from '../src/api.js';

test('API client forwards status and rejects a failed response', async () => {
  const original = globalThis.fetch;
  try {
    globalThis.fetch = async url => { assert.equal(url, '/api/projects?status=archived'); return { ok: true, json: async () => [] }; };
    assert.deepEqual(await projects('archived'), []);
    globalThis.fetch = async () => ({ ok: false });
    await assert.rejects(() => projects('active'), /Could not load/);
  } finally { globalThis.fetch = original; }
});
